def test_returns_dictionary(run, x):
    answer = run(x)
    assert isinstance(answer, dict)

def test_exact_flattened_counts(run, x):
    answer = run(x)
    values = [value for group in x['d'].values() for value in group]
    expected = {value: values.count(value) for value in values}
    assert answer == expected

def test_keys_match_observed_values(run, x):
    answer = run(x)
    expected_keys = {value for group in x['d'].values() for value in group}
    assert set(answer) == expected_keys

def test_values_are_positive_integer_counts(run, x):
    answer = run(x)
    assert all(type(count) is int and count > 0 for count in answer.values())

def test_sum_of_counts(run, x):
    answer = run(x)
    total = sum(len(group) for group in x['d'].values())
    assert sum(answer.values()) == total

def test_each_key_count_certificate(run, x):
    answer = run(x)
    values = [value for group in x['d'].values() for value in group]
    assert all(answer[key] == sum(value == key for value in values) for key in answer)

def test_per_list_aggregation(run, x):
    answer = run(x)
    keys = {value for group in x['d'].values() for value in group}
    missing = object()
    assert all(answer.get(key, missing) == sum(group.count(key) for group in x['d'].values()) for key in keys)

def test_counter_oracle(run, x):
    from collections import Counter
    answer = run(x)
    values = [value for group in x['d'].values() for value in group]
    assert answer == dict(Counter(values))

def test_empty_inputs_produce_empty_mapping(run, x):
    answer = run(x)
    has_values = any(group for group in x['d'].values())
    assert has_values or answer == {}

def test_all_observed_values_have_exact_count(run, x):
    answer = run(x)
    values = [value for group in x['d'].values() for value in group]
    missing = object()
    assert all(answer.get(value, missing) == values.count(value) for value in set(values))
